import json

def transform(grid):
    n = len(grid)
    output = [[7] * (2*n) for _ in range(2*n)]
    for i in range(n):
        for j in range(n):
            val = grid[i][j]
            if val == 7:
                continue
            output[i][j] = val
            output[j][n - 1 + (n - 1 - i)] = val
            output[n - 1 + (n - 1 - j)][i] = val
            output[n - 1 + i][n - 1 + j] = val
    return output

